'use strict';

// MODULES //

var tape = require( 'tape' );
var isnanf = require( '@stdlib/math/base/assert/is-nanf' );
var isPositiveZerof = require( '@stdlib/math/base/assert/is-positive-zerof' );
var isNegativeZerof = require( '@stdlib/math/base/assert/is-negative-zerof' );
var f32 = require( '@stdlib/number/float64/base/to-float32' );
var isAlmostSameValuef = require( '@stdlib/number/float32/base/assert/is-almost-same-value' );
var PINF = require( '@stdlib/constants/float32/pinf' );
var NINF = require( '@stdlib/constants/float32/ninf' );
var sinhf = require( './../lib' );


// FIXTURES //

var data = require( './fixtures/python/data.json' );
var large = require( './fixtures/python/large.json' );
var small = require( './fixtures/python/small.json' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof sinhf, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function computes the hyperbolic sine', function test( t ) {
	var expected;
	var x;
	var y;
	var e;
	var i;

	x = data.x;
	expected = data.expected;

	for ( i = 0; i < x.length; i++ ) {
		y = sinhf( x[ i ] );
		e = f32( expected[ i ] );
		t.strictEqual( isAlmostSameValuef( y, e, 1 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function computes the hyperbolic sine (large values)', function test( t ) {
	var expected;
	var x;
	var y;
	var e;
	var i;

	x = large.x;
	expected = large.expected;

	for ( i = 0; i < x.length; i++ ) {
		y = sinhf( x[ i ] );
		e = f32( expected[ i ] );
		t.strictEqual( isAlmostSameValuef( y, e, 1 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function computes the hyperbolic sine (small values)', function test( t ) {
	var expected;
	var x;
	var y;
	var e;
	var i;

	x = small.x;
	expected = small.expected;

	for ( i = 0; i < x.length; i++ ) {
		y = sinhf( x[ i ] );
		e = f32( expected[ i ] );
		t.strictEqual( isAlmostSameValuef( y, e, 1 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function returns `NaN` if provided `NaN`', function test( t ) {
	var v = sinhf( NaN );
	t.strictEqual( isnanf( v ), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns `+infinity` if provided `+infinity`', function test( t ) {
	var v = sinhf( PINF );
	t.strictEqual( v, PINF, 'returns expected value' );
	t.end();
});

tape( 'the function returns `-infinity` if provided `-infinity`', function test( t ) {
	var v = sinhf( NINF );
	t.strictEqual( v, NINF, 'returns expected value' );
	t.end();
});

tape( 'the function returns `+0` if provided `+0`', function test( t ) {
	var v = sinhf( 0.0 );
	t.strictEqual( isPositiveZerof( v ), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns `-0` if provided `-0`', function test( t ) {
	var v = sinhf( -0.0 );
	t.strictEqual( isNegativeZerof( v ), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns `+infinity` if provided a value greater than `MAXLOGF`', function test( t ) {
	var v = sinhf( f32( 89.0 ) );
	t.strictEqual( v, PINF, 'returns expected value' );
	t.end();
});

tape( 'the function returns `-infinity` if provided a value less than `-MAXLOGF`', function test( t ) {
	var v = sinhf( f32( -89.0 ) );
	t.strictEqual( v, NINF, 'returns expected value' );
	t.end();
});

tape( 'the function is an odd function (sinhf(-x) === -sinhf(x))', function test( t ) {
	var values;
	var v;
	var i;

	values = [ 0.1, 0.5, 1.0, 2.0, 5.0, 10.0, 50.0, 80.0 ];
	for ( i = 0; i < values.length; i++ ) {
		v = f32( values[ i ] );
		t.strictEqual( sinhf( -v ), -sinhf( v ), 'returns expected value' );
	}
	t.end();
});

tape( 'the function computes the hyperbolic sine near the branch boundary (|x| near 1)', function test( t ) {
	var v;
	var e;

	// Just below 1 (polynomial branch):
	v = sinhf( f32( 0.999 ) );
	e = f32( 1.1736587285995483 );
	t.strictEqual( isAlmostSameValuef( v, e, 1 ), true, 'returns expected value' );

	// Exactly 1 (polynomial branch):
	v = sinhf( f32( 1.0 ) );
	e = f32( 1.175201177597046 );
	t.strictEqual( isAlmostSameValuef( v, e, 1 ), true, 'returns expected value' );

	// Just above 1 (exp branch):
	v = sinhf( f32( 1.001 ) );
	e = f32( 1.1767449378967285 );
	t.strictEqual( isAlmostSameValuef( v, e, 1 ), true, 'returns expected value' );

	// Exactly -1 (polynomial branch):
	v = sinhf( f32( -1.0 ) );
	e = f32( -1.175201177597046 );
	t.strictEqual( isAlmostSameValuef( v, e, 1 ), true, 'returns expected value' );

	t.end();
});

tape( 'the function handles subnormal inputs', function test( t ) {
	var v;

	// Very small values should return x (since sinh(x) ~ x for |x| << 1):
	v = sinhf( f32( 1.0e-30 ) );
	t.strictEqual( v, f32( 1.0e-30 ), 'returns expected value' );

	v = sinhf( f32( -1.0e-30 ) );
	t.strictEqual( v, f32( -1.0e-30 ), 'returns expected value' );

	v = sinhf( f32( 1.0e-38 ) );
	t.strictEqual( v, f32( 1.0e-38 ), 'returns expected value' );

	t.end();
});
